"""
model.py -- the physical model, the normal-state DOS, and the superconducting state.

Everything here is taken from the repository
  AmirhoseynpowAsghari/power-absorbed-in-the-presence-of-external-time-dependent-perturbation
branch **master** (commit cda0d56), stage 1 = project/sc_params, stage 2 = project/ultrasonic.

Units: t = hbar = k_B = 1  (as in the repository).

Bands (project/ultrasonic/kgrid_ua.py)
    eps_s(k) = -2t (cos kx + cos ky) - 2 s V_SO |sin k|,      s = +1, -1
Gap (project/sc_params/gap_equations.py, HHM Eq. 37)
    Dbar(eps) = D0 - DS * eps / (4 t)                          -- linear in the band energy
Quasiparticle energy
    E(eps) = sqrt( (eps - mu)^2 + Dbar(eps)^2 )
Gap temperature dependence (project/ultrasonic/physics_ua.py on master)
    Delta(T) = Delta(0) * (1 - (T/Tc)^p)^q,  p = 3.434, q = 0.553
    -> both amplitudes scale rigidly:  D0(T) = phi(T) D0(0),  DS(T) = phi(T) DS(0)
       so that <|Dbar|>_k = Delta_eff(T) = phi(T) Delta_eff(0), exactly as the repository does.
"""
from __future__ import annotations

import json
import os
import numpy as np

# repository-relative default: <repo>/project (vendor/eta1_code -> vendor -> paper_correction -> project)
_DEFAULT_ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", ".."))

T_HOP = 1.0
HBAR = 1.0
KB = 1.0
OMEGA = 0.7 * T_HOP          # project/ultrasonic/parameters_ua.py: hbar*omega
B_COUP = 1.0                 # project/ultrasonic/parameters_ua.py: B
N_TARGET = 1.8850            # project/ultrasonic/parameters_ua.py: n_target
ETA = +1.0                   # project/ultrasonic/parameters_ua.py: eta = +1  (ultrasound, case I)

GAP_FIT_P = 3.434            # master: project/ultrasonic/physics_ua.py
GAP_FIT_Q = 0.553

# stage-1 output of the repository (master)
_STAGE1 = None


def stage1(repo_root: str = _DEFAULT_ROOT):
    """Load project/sc_params/results/tc_vs_vso.json (branch master)."""
    global _STAGE1
    if _STAGE1 is None:
        with open(f"{repo_root}/sc_params/results/tc_vs_vso.json") as fh:
            _STAGE1 = json.load(fh)
    return _STAGE1


def sc_params_at(VSO: float, repo_root: str = _DEFAULT_ROOT):
    """Tc, D0(0), DS(0), Delta_eff(0) from the repository's own stage-1 scan, at the nearest V_SO."""
    r = stage1(repo_root)["results"]
    V = np.asarray(r["V_SO"], float)
    i = int(np.argmin(np.abs(V - VSO)))
    return dict(VSO=float(V[i]), Tc=float(r["Tc"][i]), D0_0=float(r["D0_T0"][i]),
                DS_0=float(r["DS_T0"][i]), Deff_0=float(r["Deff_T0"][i]),
                meta=stage1(repo_root)["meta"])


def phi_gap(T: float, Tc: float, p: float = GAP_FIT_P, q: float = GAP_FIT_Q) -> float:
    """The repository's fitted gap shape (master physics_ua.Delta_T with Delta0 = 1)."""
    if T >= Tc:
        return 0.0
    return (1.0 - (T / Tc) ** p) ** q


# ---------------------------------------------------------------------------------------------
# band geometry
# ---------------------------------------------------------------------------------------------
def band_edge(VSO: float, t: float = T_HOP) -> float:
    """max_k |eps_s(k)| = 4t sqrt(1 + V_SO^2/(2t^2));  reached at (pi,0)-type points."""
    return 4.0 * t * np.sqrt(1.0 + (VSO / t) ** 2 / 2.0)


def kgrid(Nk: int):
    """Midpoint grid over the quarter zone [0,pi]^2 (the full zone is generated by the symmetries)."""
    k = (np.arange(Nk) + 0.5) * np.pi / Nk
    kx = k[:, None]
    ky = k[None, :]
    e0 = -2.0 * T_HOP * (np.cos(kx) + np.cos(ky))
    R = np.sqrt(np.sin(kx) ** 2 + np.sin(ky) ** 2)
    return e0, R


# ---------------------------------------------------------------------------------------------
# normal-state DOS  N(eps) = sum_s < delta(eps - eps_s(k)) >_k ,  normalised to  integral = 2
# ---------------------------------------------------------------------------------------------
class NormalDOS:
    """
    Histogram + Gaussian-smoothed normal DOS of the two Rashba helicity bands.

    Differences from the repository's project/ultrasonic/dos_ua.py (both are defects there):
      * normalisation: the repository's prefactor 1/(pi^1.5 sigma t) with norm = dk^2/(2pi)^2
        gives integral N deps = 0.643 instead of 2.  Here it is renormalised to exactly 2.
      * band support: the repository interpolates its table on [-6, 6] and returns a nonzero
        (spurious) Gaussian tail above the band edge.  Here N(eps) = 0 exactly for |eps| > W_band.
    Both matter for W_N; the ratio W/W_N is what we report, and it is only meaningful if the two
    integrals use the *same* N.
    """

    def __init__(self, VSO: float, Nk: int = 1400, nbins: int = 6000, smooth: float = 0.02,
                 t: float = T_HOP):
        self.VSO, self.t, self.smooth = VSO, t, smooth
        self.Wband = band_edge(VSO, t)
        edges = np.linspace(-self.Wband, self.Wband, nbins + 1)
        de = edges[1] - edges[0]
        self.de = de
        e0, R = kgrid(Nk)
        cnt = np.zeros(nbins)
        wsum = np.zeros(nbins)          # sum of eps inside each bin (for the exact mean eps)
        for s in (+1.0, -1.0):
            e = (e0 - 2.0 * s * VSO * R).ravel()
            idx = np.searchsorted(edges, e) - 1
            inside = (idx >= 0) & (idx < nbins)
            idx = idx[inside]
            cnt += np.bincount(idx, minlength=nbins)
            wsum += np.bincount(idx, weights=e[inside], minlength=nbins)
        from scipy.ndimage import gaussian_filter1d
        raw = cnt / (Nk ** 2 * de)                       # quarter-zone midpoint grid -> full zone
        dens = gaussian_filter1d(raw, smooth / de, mode="constant")
        dens *= 2.0 / (dens.sum() * de)                  # exact normalisation: integral N deps = 2
        self.grid = 0.5 * (edges[1:] + edges[:-1])
        self.dens = dens
        self.eps_mean = np.where(cnt > 0, wsum / np.maximum(cnt, 1), self.grid)
        # quadrature grid for the "state b" sum (midpoint rule, weight = N deps)
        self.eps_i = self.grid.copy()
        self.w_i = self.dens * de
        # for the brute-force k-space cross-check: the exact bin index of every k point
        self._kdata = (e0, R, edges)

    def N(self, eps):
        eps = np.asarray(eps, float)
        out = np.interp(eps, self.grid, self.dens, left=0.0, right=0.0)
        return np.where(np.abs(eps) <= self.Wband, out, 0.0)     # exact band support

    def bin_of(self, eps):
        """bin index of a band energy (clipped); used by the brute-force check."""
        edges = self._kdata[2]
        return np.clip(np.searchsorted(edges, eps) - 1, 0, len(self.grid) - 1)

    def check(self):
        tot = self.w_i.sum()
        return dict(integral=tot, Wband=self.Wband, N_at_mu_region=float(self.N(3.6)),
                    nbins=len(self.grid), de=self.de)


# ---------------------------------------------------------------------------------------------
# chemical potential from the number equation, for a given (possibly energy-dependent) gap
# ---------------------------------------------------------------------------------------------
def electron_density(mu: float, D0: float, DS: float, T: float, VSO: float,
                     Nk: int = 300, t: float = T_HOP) -> float:
    """
    n(mu) = 1 - (1/2) < xi/E tanh(E / 2T) >_k summed over both helicities
    (identical to project/ultrasonic/physics_ua.compute_electron_density, except that the gap is
    the energy-dependent Dbar(eps) = D0 - DS eps/4t rather than one constant).
    """
    e0, R = kgrid(Nk)
    tot = 0.0
    for s in (+1.0, -1.0):
        eps = e0 - 2.0 * s * VSO * R
        xi = eps - mu
        Dbar = D0 - DS * eps / (4.0 * t)
        E = np.hypot(xi, Dbar)
        th = np.tanh(E / (2.0 * KB * T)) if T > 1e-12 else np.ones_like(E)
        tot += np.mean(xi / np.maximum(E, 1e-300) * th)
    return 1.0 - 0.5 * tot


def solve_mu(T: float, D0: float, DS: float, VSO: float, n_tgt: float = N_TARGET,
             Nk: int = 300, bracket=(-100.0, 100.0)) -> float:
    """mu(T) such that n(mu) = n_tgt.  D0 = DS = 0 gives the normal-state mu_N(T)."""
    from scipy.optimize import brentq
    f = lambda mu: electron_density(mu, D0, DS, T, VSO, Nk=Nk) - n_tgt
    return brentq(f, *bracket, xtol=1e-12)


# ---------------------------------------------------------------------------------------------
# the superconducting state at a given T/Tc, using the repository's stage-1 numbers
# ---------------------------------------------------------------------------------------------
class SCState:
    """
    D0(T), DS(T), Delta_eff(T), mu_SC(T), mu_N(T) at a given T (fraction of the repository's Tc).

    mu_SC : number equation with the energy-dependent gap  (self-consistent with the gap used below)
    mu_N  : number equation with D0 = DS = 0              (the normal state of the same model)
    """

    def __init__(self, VSO: float = None, Nk_mu: int = 300,
                 repo_root: str = _DEFAULT_ROOT,
                 params: dict = None, n_tgt: float = None):
        if params is None:
            p = sc_params_at(VSO, repo_root)
            self.meta = p["meta"]
        else:                            # explicit stage-1 numbers (paper parameter sets)
            p = params
            self.meta = {"source": "explicit params"}
        self.VSO = p["VSO"]
        self.Tc, self.D0_0, self.DS_0, self.Deff_0 = p["Tc"], p["D0_0"], p["DS_0"], p["Deff_0"]
        self.n_tgt = N_TARGET if n_tgt is None else n_tgt
        self.Nk_mu = Nk_mu

    @classmethod
    def from_params(cls, VSO, Tc, D0_0, DS_0, Deff_0, n_tgt=N_TARGET, Nk_mu=300):
        """SC state built from explicit stage-1 numbers instead of the repository json."""
        return cls(params=dict(VSO=VSO, Tc=Tc, D0_0=D0_0, DS_0=DS_0, Deff_0=Deff_0),
                   n_tgt=n_tgt, Nk_mu=Nk_mu)

    def at(self, frac: float, mu_mode: str = "consistent"):
        T = frac * self.Tc
        phi = phi_gap(T, self.Tc)
        D0, DS = phi * self.D0_0, phi * self.DS_0
        Deff = phi * self.Deff_0
        mu_N = solve_mu(T, 0.0, 0.0, self.VSO, n_tgt=self.n_tgt, Nk=self.Nk_mu)
        if mu_mode == "normal":          # W_N convention: use mu_N everywhere
            mu = mu_N
        else:                            # repository convention: mu from the SC number equation
            mu = solve_mu(T, D0, DS, self.VSO, n_tgt=self.n_tgt, Nk=self.Nk_mu)
        return dict(frac=frac, T=T, phi=phi, D0=D0, DS=DS, Deff=Deff, mu=mu, mu_N=mu_N)


if __name__ == "__main__":
    for v in (0.0, 0.4082, 0.8):
        p = sc_params_at(v)
        print(f"V_SO={p['VSO']:.4f}  Tc={p['Tc']:.4f}  D0(0)={p['D0_0']:.4f}  "
              f"DS(0)={p['DS_0']:.4f}  Deff(0)={p['Deff_0']:.4f}  band edge={band_edge(v):.4f}")
    d = NormalDOS(0.4082, Nk=400)
    print("DOS check:", d.check())
